      "path": ".claude/skills/add-feature.md",
      "aliases": ["/add-feature"]
    },
    {
      "name": "derrick-status",
      "description": "Show current batch status, in-flight tickets, and foreman state in a caveman-compressed summary.",
      "path": ".claude/skills/derrick-status.md"
    }
  ],
  "hooks": {
    "PreToolUse": "derrick scrub",
    "PostToolUse": "derrick caveman --intensity lite"
  },
  "requires": {
    "cli": "derrick",
    "min_version": "0.1.0"
  }
}

