 )
 }
 None => "last assay: (none yet)".to_owned(),
 };

 // ── row 6: token spend (today only) ─────────────────────────────────
 let ts = &app.data.token_summary;
 let tokens_line = if ts.today_in == 0 && ts.today_out == 0 {
